//! `WebAuthn` hardware passkey credential entities and database query models.

use crate::{error::internal, model::Result};
use chrono::Utc;
use serde::Serialize;
use sqlx::SqlitePool;
use webauthn_rs::prelude::{CredentialID, Passkey};

/// A complete `WebAuthn` credential record stored in the `webauthn_credentials` table.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Record {
    /// Unique credential identifier generated by the authenticator during registration.
    pub credential_id: Vec<u8>,
    /// Foreign key referencing the owning user's ID in `users`.
    pub user_id: i64,

    /// Serialized `WebAuthn` authenticator state (`webauthn-rs::Passkey`).
    pub passkey_data: Vec<u8>,
    /// Monotonically increasing signature counter used for clone detection.
    pub counter: i64,

    /// Client-encrypted human-readable label and metadata (max 1024 bytes).
    pub encrypted_metadata: Vec<u8>,

    /// Unix timestamp (seconds) when this credential was registered.
    pub created_at: i64,
    /// Unix timestamp (seconds) when this credential was last used for authentication.
    pub last_used: i64,
}

/// A sanitized summary of a passkey for client credential listing.
#[derive(Debug, Serialize)]
pub struct Summary {
    /// Hex-encoded credential identifier.
    pub credential_id: String,
    /// Hex-encoded encrypted metadata blob.
    pub encrypted_metadata: String,
    /// Unix timestamp (seconds) when the passkey was registered.
    pub created_at: i64,
    /// Unix timestamp (seconds) when the passkey was last used for authentication.
    pub last_used: i64,
}

impl Record {
    /// Constructs a new passkey record from a verified `WebAuthn` passkey.
    ///
    /// # Errors
    /// Returns an error if serializing the passkey state to JSON fails.
    pub fn new(
        user_id: i64,
        passkey: &Passkey,
        encrypted_metadata: Vec<u8>,
    ) -> Result<Self> {
        let Ok(passkey_data) = serde_json::to_vec(passkey) else {
            Err(internal::Error::Message(
                "Failed to serialize passkey state",
            ))?
        };

        let now = Utc::now().timestamp();

        Ok(Self {
            credential_id: passkey.cred_id().to_vec(),
            user_id,
            passkey_data,
            counter: 0,
            encrypted_metadata,
            created_at: now,
            last_used: 0,
        })
    }

    /// Inserts a new passkey credential record into the `webauthn_credentials` table.
    ///
    /// # Errors
    /// - Returns [`crate::model::Error::UniqueViolation`] if `credential_id` is already registered.
    /// - Returns [`crate::model::Error::ForeignKeyViolation`] if `user_id` does not exist in `users`.
    /// - Returns [`crate::model::Error::CheckViolation`] if `encrypted_metadata` exceeds 1024 bytes.
    /// - Returns [`crate::model::Error::Database`] if the database query fails.
    pub async fn create(pool: &SqlitePool, record: &Self) -> Result<()> {
        sqlx::query!(
            r#"
            INSERT
                INTO webauthn_credentials (
                    credential_id,
                    user_id,
                    encrypted_metadata,
                    passkey_data,
                    counter,
                    created_at,
                    last_used
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
        "#,
            record.credential_id,
            record.user_id,
            record.encrypted_metadata,
            record.passkey_data,
            record.counter,
            record.created_at,
            record.last_used
        )
        .execute(pool)
        .await?;

        Ok(())
    }

    /// Fetches a passkey credential record by its raw `credential_id`.
    ///
    /// # Errors
    /// - Returns [`crate::model::Error::Database`] if the database query fails.
    pub async fn find(pool: &SqlitePool, id: &[u8]) -> Result<Option<Self>> {
        let record = sqlx::query_as!(
            Self,
            r#"
            SELECT
                credential_id AS 'credential_id!',
                user_id,
                encrypted_metadata,
                passkey_data AS 'passkey_data!',
                counter,
                created_at,
                last_used
            FROM
                webauthn_credentials
            WHERE
                credential_id = ?
        "#,
            id
        )
        .fetch_optional(pool)
        .await?;

        Ok(record)
    }

    /// Lists all passkey summaries for a given user ordered newest to oldest.
    ///
    /// # Errors
    /// - Returns [`crate::model::Error::Database`] if the database query fails.
    pub async fn list_for_user(
        pool: &SqlitePool,
        user_id: i64,
    ) -> Result<Vec<Summary>> {
        let rows = sqlx::query!(
            r#"
            SELECT
                credential_id AS 'credential_id!',
                encrypted_metadata,
                created_at,
                last_used
            FROM
                webauthn_credentials
            WHERE
                user_id = ?
            ORDER BY
                created_at DESC
        "#,
            user_id
        )
        .fetch_all(pool)
        .await?;

        Ok(rows
            .into_iter()
            .map(|r| Summary {
                credential_id: hex::encode(r.credential_id),
                encrypted_metadata: hex::encode(r.encrypted_metadata),
                created_at: r.created_at,
                last_used: r.last_used,
            })
            .collect())
    }

    /// Updates the signature counter and last-used timestamp after a successful authentication.
    ///
    /// # Errors
    /// - Returns [`crate::model::Error::Database`] if the database query fails.
    pub async fn update_counter(
        pool: &SqlitePool,
        credential_id: &[u8],
        passkey_data: &[u8],
        new_counter: i64,
        last_used: i64,
    ) -> Result<()> {
        sqlx::query!(
            r#"
            UPDATE
                webauthn_credentials
            SET
                passkey_data = ?,
                counter = ?,
                last_used = ?
            WHERE
                credential_id = ?
        "#,
            passkey_data,
            new_counter,
            last_used,
            credential_id
        )
        .execute(pool)
        .await?;

        Ok(())
    }

    /// Deletes a passkey credential belonging to a specific user.
    ///
    /// Returns `true` if a row was deleted, or `false` if no matching record was found.
    ///
    /// # Errors
    /// - Returns [`crate::model::Error::Database`] if the database query fails.
    pub async fn delete(
        pool: &SqlitePool,
        credential_id: &[u8],
        user_id: i64,
    ) -> Result<bool> {
        let rows_affected = sqlx::query!(
            r#"
            DELETE
            FROM
                webauthn_credentials
            WHERE
                credential_id = ? AND
                user_id = ?
        "#,
            credential_id,
            user_id
        )
        .execute(pool)
        .await?
        .rows_affected();

        Ok(rows_affected > 0)
    }

    /// Returns a list of existing credentials for a user to exclude during registration.
    ///
    /// # Errors
    /// Returns an error if querying the database fails.
    pub async fn exclude_list_for_user(
        pool: &SqlitePool,
        user_id: i64,
    ) -> Result<Option<Vec<CredentialID>>> {
        let rows = sqlx::query!(
            r#"
            SELECT
                credential_id AS 'credential_id!'
            FROM
                webauthn_credentials
            WHERE
                user_id = ?
            "#,
            &user_id
        )
        .fetch_all(pool)
        .await?;

        if rows.is_empty() {
            return Ok(None);
        }

        Ok(Some(
            rows.into_iter()
                .map(|r| CredentialID::from(r.credential_id))
                .collect(),
        ))
    }
}

